    for x in numbers:
        if x < 0:
            counts['negative'] += 1
        elif x == 0:
            counts['zero'] += 1
        else:
            counts['positive'] += 1
    return counts

def count_open_paths(grid):
    n, m = len(grid), len(grid[0])
    ways = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if grid[i][j] < 0:
                continue
            if i == 0 and j == 0:
                ways[i][j] = 1
            else:
                ways[i][j] = (ways[i - 1][j] if i > 0 else 0) + (ways[i][j - 1] if j > 0 else 0)
    return ways[-1][-1]

