def count_positive_regions(grid):
    seen = set()
    count = 0
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] > 0 and (r, c) not in seen:
                count += 1
                seen.add((r, c))
                stack = [(r, c)]
                while stack:
                    i, j = stack.pop()
                    for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                        if 0 <= a < len(grid) and 0 <= b < len(grid[a]) and grid[a][b] > 0 and (a, b) not in seen:
                            seen.add((a, b))
                            stack.append((a, b))
    return count

