def shortest_stretch_reaching(numbers, target):
    best = 0
    left = 0
    total = 0
    for right, x in enumerate(numbers):
        total += x
        while left < right and total - numbers[left] >= target:
            total -= numbers[left]
            left += 1
        if total >= target and (best == 0 or right - left + 1 < best):
